    progress: z
        .enum([
        "queued",
        "preparing",
        "creating",
        "building",
        "starting",
        "finalizing",
        "running",
        "failed",
        "stopping",
        "stopped",
        "deleting",
        "degraded",
    ])
        .optional(),
    statusMessage: z.string().nullable().optional(),
    generation: z.number(),
    observedGeneration: z.number().nullable().optional(),
    engineGeneration: z.number().nullable().optional(),
